// Writes src/theme/m3-roles.json: the SpaceUI dark scheme roles of @aphrody/m3-theme/spaceui.css (generated by
// crates/aphrody-m3-tokens), as plain values for NativeWind (tailwind.config.js) and for React Native props
// that take a colour string (icons, placeholders, switches). React Native has no CSS custom properties, so the
// values are copied from the generated sheet at build time; nothing is hand-picked. The same roles are written
// into the committed native chrome (Android colors.xml/styles.xml, iOS splash colour set).
//
//   bun scripts/m3-roles.ts           # rewrite the outputs
//   bun scripts/m3-roles.ts --check   # fail when one is stale

import { join } from "node:path";

const sheetPath = Bun.resolveSync("@aphrody/m3-theme/spaceui.css", import.meta.dir);
const sheet = await Bun.file(sheetPath).text();

// The first block (`:root, .dark`) is the SpaceUI dark scheme, the default the mobile app renders.
const block = /:root,\s*\.dark\s*\{([^}]*)\}/.exec(sheet)?.[1];
if (!block) throw new Error(`${sheetPath}: no ':root, .dark' scheme block`);

const camel = (name: string) => name.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
const dark: Record<string, string> = {};
for (const [, , name, value] of block.matchAll(/--md-(sys|ext)-color-([a-z-]+):\s*(#[0-9a-f]{6})\s*;/gi))
    dark[camel(name!)] = value!.toLowerCase();
if (!dark["primary"] || !dark["surface"] || !dark["success"])
    throw new Error(`${sheetPath}: the dark scheme is missing core roles`);

const root = join(import.meta.dir, "..");
const outputs = new Map<string, string>();
outputs.set(
    "src/theme/m3-roles.json",
    `${JSON.stringify(
        {
            $generated:
                "GENERATED by apps/spacedrive/apps/mobile/scripts/m3-roles.ts from @aphrody/m3-theme/spaceui.css. Do not hand-edit.",
            dark,
        },
        null,
        "	",
    )}
`,
);

// The native chrome Expo prebuild writes from app.config.ts (splash, status bar, colorPrimary), kept on the same
// roles in the committed android/ and ios/ projects. iconBackground is the adaptive icon artwork (app.json).
const surface = dark["surface"]!;
const primary = dark["primary"]!;
const readNative = async (path: string) => Bun.file(join(root, path)).text();
const setColor = (xml: string, name: string, value: string) => {
    const re = new RegExp(`(<color name="${name}">)[^<]*(</color>)`);
    if (!re.test(xml)) throw new Error(`colors.xml: no ${name}`);
    return xml.replace(re, `$1${value}$2`);
};
const colorsXml = "android/app/src/main/res/values/colors.xml";
let colors = await readNative(colorsXml);
colors = setColor(colors, "splashscreen_background", surface);
colors = setColor(colors, "colorPrimary", primary);
colors = setColor(colors, "colorPrimaryDark", surface);
outputs.set(colorsXml, colors);
const stylesXml = "android/app/src/main/res/values/styles.xml";
const styles = await readNative(stylesXml);
const statusBar = /(<item name="android:statusBarColor">)[^<]*(<\/item>)/;
if (!statusBar.test(styles)) throw new Error(`${stylesXml}: no android:statusBarColor`);
outputs.set(stylesXml, styles.replace(statusBar, `$1${surface}$2`));
const channel = (hex: string, at: number) => (Number.parseInt(hex.slice(at, at + 2), 16) / 255).toFixed(14);
outputs.set(
    "ios/Spacedrive/Images.xcassets/SplashScreenBackground.colorset/Contents.json",
    `${JSON.stringify(
        {
            colors: [
                {
                    color: {
                        components: {
                            alpha: "1.000",
                            blue: channel(surface, 5),
                            green: channel(surface, 3),
                            red: channel(surface, 1),
                        },
                        "color-space": "srgb",
                    },
                    idiom: "universal",
                },
            ],
            info: { version: 1, author: "expo" },
        },
        null,
        2,
    )}
`,
);

const check = process.argv.includes("--check");
let stale = false;
for (const [path, content] of outputs) {
    const current = await Bun.file(join(root, path))
        .text()
        .catch(() => "");
    if (current === content) continue;
    if (check) {
        console.error(`${path} is stale (run bun scripts/m3-roles.ts)`);
        stale = true;
    } else await Bun.write(join(root, path), content);
}
if (stale) process.exit(1);
